package com.library.catalog.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime; import java.util.*;
@Entity @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Book{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String isbn;@Column(nullable=false)private String title;@Column(length=5000)private String description;private Integer publicationYear;private String language;private Integer pageCount;private String coverUrl;private String shelfLocation;@ManyToOne(optional=false)private Author author;@ManyToOne(optional=false)private Category category;@ManyToOne private Publisher publisher;@Builder.Default private Integer totalCopies=0;@Builder.Default private Integer availableCopies=0;@Builder.Default private Boolean featured=false;private Double rating;private LocalDateTime createdAt;private LocalDateTime updatedAt;@OneToMany(mappedBy="book",cascade=CascadeType.ALL,orphanRemoval=true)@Builder.Default private List<BookCopy> copies=new ArrayList<>();@PrePersist void c(){createdAt=updatedAt=LocalDateTime.now();if(rating==null)rating=4.5;}@PreUpdate void u(){updatedAt=LocalDateTime.now();}}

